fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let colw: i32 = w / 24;
    let mut tmp = [0; 24];
    let mut i: i32 = 0;
    while i < 24 {
        tmp[i] = host::display::state_get(8 + i);
        i = i + 1;
    }
    if host::display::pointer_down() == 1 {
        let mut c: i32 = host::display::pointer_x() / colw;
        if c < 0 { c = 0; }
        if c > 23 { c = 23; }
        tmp[c] = tmp[c] + 400;
        if tmp[c] > 4080 { tmp[c] = 4080; }
    }
    let mut nxt = [0; 24];
    i = 0;
    while i < 24 {
        let left: i32 = if i > 0 { tmp[i - 1] } else { 0 };
        let right: i32 = if i < 23 { tmp[i + 1] } else { 0 };
        nxt[i] = tmp[i] + (left + right - 2 * tmp[i]) / 4;
        nxt[i] = nxt[i] - nxt[i] / 128;
        if nxt[i] < 0 { nxt[i] = 0; }
        i = i + 1;
    }
    host::display::clear(0x0a0a0c);
    i = 0;
    while i < 24 {
        host::display::state_set(8 + i, nxt[i]);
        let r: i32 = nxt[i] / 16;
        let b: i32 = 255 - r;
        let bh: i32 = 40 + nxt[i] / 16;
        host::display::fill_rect(i * colw, h - bh, colw - 1, bh, r * 65536 + 32 * 256 + b);
        i = i + 1;
    }
    host::display::draw_string(8, 8, "HOLD TO HEAT THE ROD", 0x808080, 1);
    host::display::present();
}
